"""Compute gross Nexus costs from actual recipe JSON; never double-charge intermediates."""
from pathlib import Path
from collections import Counter
from fractions import Fraction
from math import ceil
import json
ROOT=Path(__file__).resolve().parents[1];RES=ROOT/'revoindustry/src/main/resources';recipes={}
for p in (RES/'data/revoindustry/recipe/nexus').glob('*.json'):
 d=json.loads(p.read_text());out=d.get('item_outputs',[])
 if out:recipes[out[0]['item']]=(p.stem,d,out[0]['amount'])
manifest=json.loads((RES/'nexus/structures.json').read_text());top=Counter(c['block'] for kind,bp in manifest['structures'].items() if kind!='nexus_builder' for c in bp['cells']);top['revoindustry:nexus_construction_program']=1
demand=Counter();leaves=Counter();uses=Counter();reusable={}
def expand(item,n,path=(),capital=False):
 if (item.startswith('revoindustry:nexus_mould_') or item=='revoindustry:nexus_containment_cell') and not capital:
  reusable[item]=max(reusable.get(item,0),8 if item.endswith('containment_cell') else 1);return
 assert item not in path,('Dependency cycle',path,item)
 demand[item]+=n
 if item not in recipes:leaves[item]+=n;return
 name,recipe,count=recipes[item];batches=n/count;uses[name]+=batches
 returned={s['item'] for s in recipe.get('item_outputs',[])[1:]}
 for s in recipe.get('item_inputs',[]):
  if s.get('probability',1)==0:continue
  if s['item'] in returned and 'nexus_mould_' in s['item']:reusable[s['item']]=max(reusable.get(s['item'],0),1);continue
  expand(s['item'],batches*s['amount'],path+(item,))
for item,n in top.items():expand(item,Fraction(n))
for item,n in list(reusable.items()):expand(item,Fraction(n),capital=True)
totals={name:int(demand['revoindustry:'+name]) for name in ['nexus_alloy_ingot','phase_lattice','astral_essence']};totals['nether_stars']=int(leaves['minecraft:nether_star']);totals['mi_singularities']=int(leaves['modern_industrialization:singularity']);totals['alloy_batch_rounded']=ceil(totals['nexus_alloy_ingot']/8)*8
assert totals['phase_lattice']==1536 and totals['astral_essence']==3072 and totals['nether_stars']==6144 and totals['mi_singularities']==6,totals
assert abs(totals['nexus_alloy_ingot']/6144-1)<.05,totals
# The cheap builder recipe must not acquire an endgame ingredient dependency.
_,builder,_=recipes['revoindustry:nexus_builder'];assert not any(s['item'].startswith('revoindustry:') or s['item']=='minecraft:nether_star' or 'singularity' in s['item'] for s in builder['item_inputs'])
report={'result':'PASS','scope':'One of each three processing multiblocks, the 814-block portal, the embedded builder and its retained program. Native MI upstream recipes stop at the listed native components; their own ingredients are additional.','totals':totals,'targets':{'nexus_alloy_ingot':6144,'phase_lattice':1536,'astral_essence':3072,'nether_stars':6144,'mi_singularities':6},'reusableCapital':reusable,'nativeAndVanillaInputs':{k:float(v) for k,v in sorted(leaves.items())},'recipeBatchesUnrounded':{k:float(v) for k,v in sorted(uses.items())},'topLevelBlocksAndProgram':dict(sorted(top.items())),'coreRetainedForProgram':True,'notes':['Alloy is needed at 6101 ingots; eight-ingot batches require 6104, leaving three spare.','Compacted drops and catalysts use real batch recipes; no stack exceeds64.','Moulds return physically from the caster. Containment cells return from native centrifuging, requiring eight startup cells when batches are recycled.','Recipe amounts are gross material requirements, not a second invoice on top of the same intermediates.','Parallel factories need extra moulds/cells. Existing machine-tool infrastructure, fuel, fluids, cable, extra buffers and recipe overclocks are outside this structural bill.']}
(ROOT/'docs/nexus-material-ledger.json').write_text(json.dumps(report,indent=2)+'\n')
lines=['# Nexus survival material ledger','','Generated from the production recipe JSON by `scripts/audit_nexus_progression.py`. Includes all three production multiblocks, one portal and the builder/program. Native MI component manufacture, fluids, power and factory infrastructure remain additional.','','| Gross material | Proposed target | Actual |','| --- | ---: | ---: |']
for key,target in report['targets'].items():lines.append(f'| {key.replace("_"," ")} | {target:,} | {totals[key]:,} |')
lines+=['','The alloy batch requirement is **6,104 ingots**, including three spare. Lattices and essence embedded inside the Core, ring, beacons, contacts and controller are included once. Six singularities retain the native MI requirement of **384 nukes**, plus the native ultradense-ball and nuclear costs.','','## Automation chain','','1. Mixer -> EBF with UU Matter -> Vacuum Freezer -> cooled Nexus Alloy.','2. Pressure Casting Plant with the selected physical mould, nitrogen and Cryofluid -> rough casting + returned mould + warm coolant. Native MI Compressor finishes the casting.','3. MI Chemical Reactor prepares cleaning solution and copper/sulfuric electrolyte. Electroplating Line performs clean, plate and rinse as three saved native recipes. Return each output intermediate to its input hatch; use MI slot/fluid locks for the dedicated baths and waste outlets.','4. Compressor and Polarizer prepare different targets. Collider accepts both targets, Astral Essence, reusable containment cells, native fusion Helium Plasma and Cryofluid. Unbalanced injections wait in their native saved hatch inventories. No same-tick timing is required.','5. MI Centrifuge opens the stabilized exotic-matter cells and returns their empty containment cells. The MI Assembler combines the recovered matter with rinsed substrates into Phase Lattices.','6. Six Ignition Cells and finished cast/plated components assemble the Core. The server-side MI program recipe requires that completed Core with consumption probability zero: the Core remains available for the portal. A blank program cannot operate the builder.','7. Build with individual supplied blocks, then power the full portal at 1,024 EU/t. The server awards the final stabilization advancement; the final quest uses that advancement.','','## Waste recovery','','Spent electrolyte centrifuging returns one copper dust per 1,000 mB, at most25% of the copper originally used to make it. Wastewater treatment returns 750 mB water per 1,000 mB. Warm coolant freezing returns 750 mB Cryofluid per 1,000 mB. These are lossy loops; fresh feed is always required.','','## Renewability and gates','','Platinum drilling is Nuclear Survey Core-gated at 512 EU/t. Native MI sulfuric solution/centrifuging supplies iridium; no quarry is required. A dedicated core-gated Deep Debris program supplies one Ancient Debris per 1,200 ticks, replacing the impractical 64-result wait for bulk endgame work. Existing program indices 0–10 are unchanged. Monazite is also available as a late drill program. Gems remain sludge products.','','Astral Essence compacts nine mob-drop streams separately. Each Essence costs two Nether Stars and eight each of rotten flesh, bones, string, leather, slimeballs, blaze rods, pearls, ghast tears and magma cream. At 3,072 essence this is 24,576 of each drop. Biological Catalysts additionally consume compost, silk cocoons, paper, rubber, crop nutrients and charcoal/cotton reinforcement. These costs connect cultivation, trees, harvester programs and Wither processing to MI chemistry.','','## Builder controls','','Place the builder at the centre of the bottom layer. Place the MI input hatch left of it, output hatch right of it, and power hatch immediately behind it. Right-click the controller for the materials interface. Click a slot with matching items to deposit or with an empty cursor to withdraw up to 64. Shift-click inventory stacks to deposit. Counts include already placed blocks while stored quantities remain available for withdrawal. The Box toggle shows the build volume. Clear the entire volume apart from the builder and its hatches before starting. Charge 100,000,000 EU, insert the retained program and fill the bill before pressing Build. Construction places 810 supplied blocks around its four existing blocks.','','Use native MI recipe locking from EMI when ingredients match multiple Assembler recipes. A higher-tier energy hatch charges the builder faster. At a sustained 8,192 EU/t, the precharge takes about ten minutes.','','## Required native MI processing','','Mixer, Electric Blast Furnace, Vacuum Freezer, Compressor, Assembler, Chemical Reactor, Macerator, Wiremill, Polarizer, Centrifuge, Electrolyzer, nuclear processing, fusion, UU Matter, superconductors and quantum circuits all have explicit inputs in this graph. Optional MI machines, quarrying, Revo storage and cosmetics sit outside this recipe chain.','','The current Wither recipe takes 75 seconds per star. 6,144 stars require 128 h in one chamber or 8 h across 16 supplied chambers. This is a calculated throughput estimate, not a complete survival playthrough.']
(ROOT/'docs/NEXUS-MATERIAL-LEDGER.md').write_text('\n'.join(lines)+'\n');print(totals)
